PRECEDENCE = {'+': 1, '-': 1, '*': 2, '/': 2}

def apply_op(values, ops):
    op = ops.pop()
    b, a = values.pop(), values.pop()
    if op == '+':
        values.append(a + b)
    elif op == '-':
        values.append(a - b)
    elif op == '*':
        values.append(a * b)
    else:
        values.append(a / b)

def evaluate(expr):
    values, ops, i = [], [], 0
    while i < len(expr):
        ch = expr[i]
        if ch == ' ':
            i += 1
            continue
        if ch.isdigit():
            number = ''
            while i < len(expr) and (expr[i].isdigit() or expr[i] == '.'):
                number += expr[i]
                i += 1
            values.append(float(number))
            continue
        if ch == '(':
            ops.append(ch)
        elif ch == ')':
            while ops and ops[-1] != '(':
                apply_op(values, ops)
            ops.pop()
        else:
            while ops and ops[-1] != '(' and PRECEDENCE[ops[-1]] >= PRECEDENCE[ch]:
                apply_op(values, ops)
            ops.append(ch)
        i += 1
    while ops:
        apply_op(values, ops)
    return values[0]

for expr in ('2 + 3 * 4', '(2 + 3) * 4', '2 + 3 * (4 - 1) / 3', '10 - 4 - 3'):
    print(f'{expr:22} = {evaluate(expr)}')

