    for raw in answers:
        raw = raw.strip()
        if not raw:
            continue
        try:
            port = int(raw)
        except ValueError:
            print(f'  reject {raw!r}: not a number')
            continue
        if not 0 < port < 65536:
            print(f'  reject {raw!r}: out of range')
            continue
        return port
    return default

