def merge_sorted(a, b):
    i = j = dupes = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] < b[j]:
            out.append(a[i]); i += 1
        elif a[i] > b[j]:
            out.append(b[j]); j += 1
        else:
            out.append(a[i]); out.append(b[j])
            dupes += 1
            i += 1; j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out, dupes

